    @expose('/action')
    @login_required
    def action(self):
        action = request.args.get('action')
        dag_id = request.args.get('dag_id')
        task_id = request.args.get('task_id')
        origin = request.args.get('origin')
        dag = dagbag.get_dag(dag_id)
        task = dag.get_task(task_id)
        execution_date = request.args.get('execution_date')
        execution_date = dateutil.parser.parse(execution_date)
        confirmed = request.args.get('confirmed') == "true"
        upstream = request.args.get('upstream') == "true"
        downstream = request.args.get('downstream') == "true"
        if action == "run":
            from airflow.executors import DEFAULT_EXECUTOR as executor
            from airflow.executors import CeleryExecutor
            if not isinstance(executor, CeleryExecutor):
                flash("Only works with the CeleryExecutor, sorry", "error")
                return redirect(origin)
            force = request.args.get('force') == "true"
            deps = request.args.get('deps') == "true"
            ti = models.TaskInstance(task=task, execution_date=execution_date)
            executor.start()
            executor.queue_task_instance(
                ti, force=force, ignore_dependencies=deps)
            executor.heartbeat()
            flash(
                "Sent {} to the message queue, "
                "it should start any moment now.".format(ti))
            return redirect(origin)
        elif action == 'clear':
            future = request.args.get('future') == "true"
            past = request.args.get('past') == "true"
            dag = dag.sub_dag(
                task_regex=r"^{0}$".format(task_id),
                include_downstream=downstream,
                include_upstream=upstream)
            end_date = execution_date if not future else None
            start_date = execution_date if not past else None
            if confirmed:
                count = dag.clear(
                    start_date=start_date,
                    end_date=end_date)
                flash("{0} task instances have been cleared".format(count))
                return redirect(origin)
            else:
                tis = dag.clear(
                    start_date=start_date,
                    end_date=end_date,
                    dry_run=True)
                if not tis:
                    flash("No task instances to clear", 'error')
                    response = redirect(origin)
                else:
                    details = "\n".join([str(t) for t in tis])
                    response = self.render(
                        'airflow/confirm.html',
                        message=(
                            "Here's the list of task instances you are about "
                            "to clear:"),
                        details=details,)
                return response
        elif action == 'success':
            # Flagging tasks as successful
            session = settings.Session()
            task_ids = [task_id]
            if downstream:
                task_ids += [
                    t.task_id
                    for t in task.get_flat_relatives(upstream=False)]
            if upstream:
                task_ids += [
                    t.task_id
                    for t in task.get_flat_relatives(upstream=True)]
            TI = models.TaskInstance
            tis = session.query(TI).filter(
                TI.dag_id == dag_id,
                TI.execution_date == execution_date,
                TI.task_id.in_(task_ids)).all()
            if confirmed:
                updated_task_ids = []
                for ti in tis:
                    updated_task_ids.append(ti.task_id)
                    ti.state = State.SUCCESS
                session.commit()
                to_insert = list(set(task_ids) - set(updated_task_ids))
                for task_id in to_insert:
                    ti = TI(
                        task=dag.get_task(task_id),
                        execution_date=execution_date,
                        state=State.SUCCESS)
                    session.add(ti)
                    session.commit()
                session.commit()
                session.close()
                flash("Marked success on {} task instances".format(
                    len(task_ids)))
                return redirect(origin)
            else:
                if not task_ids:
                    flash("No task instances to mark as successful", 'error')
                    response = redirect(origin)
                else:
                    tis = []
                    for task_id in task_ids:
                        tis.append(TI(
                            task=dag.get_task(task_id),
                            execution_date=execution_date,
                            state=State.SUCCESS))
                    details = "\n".join([str(t) for t in tis])
                    response = self.render(
                        'airflow/confirm.html',
                        message=(
                            "Here's the list of task instances you are about "
                            "to mark as successful:"),
                        details=details,)
                return response
    @expose('/tree')
    @login_required
    @wwwutils.gzipped
    def tree(self):
        dag_id = request.args.get('dag_id')
        blur = conf.getboolean('webserver', 'demo_mode')
        dag = dagbag.get_dag(dag_id)
        root = request.args.get('root')
        if root:
            dag = dag.sub_dag(
                task_regex=root,
                include_downstream=False,
                include_upstream=True)
        session = settings.Session()
        start_date = dag.start_date
        if not start_date and 'start_date' in dag.default_args:
            start_date = dag.default_args['start_date']
        base_date = request.args.get('base_date')
        num_runs = request.args.get('num_runs')
        num_runs = int(num_runs) if num_runs else 25
        if not base_date:
            base_date = dag.latest_execution_date or datetime.now()
        else:
            base_date = dateutil.parser.parse(base_date)
        base_date = utils.round_time(base_date, dag.schedule_interval)
        form = TreeForm(data={'base_date': base_date, 'num_runs': num_runs})
        start_date = dag.start_date
        if not start_date and 'start_date' in dag.default_args:
            start_date = dag.default_args['start_date']
        if start_date:
            base_date = utils.round_time(base_date, dag.schedule_interval, start_date)
        else:
            base_date = utils.round_time(base_date, dag.schedule_interval)

        from_date = (base_date - (num_runs * dag.schedule_interval))
        dates = utils.date_range(
            from_date, base_date, dag.schedule_interval)
        task_instances = {}
        for ti in dag.get_task_instances(session, from_date):
            task_instances[(ti.task_id, ti.execution_date)] = ti
        expanded = []
        # The default recursion traces every path so that tree view has full
        # expand/collapse functionality. After 5,000 nodes we stop and fall
        # back on a quick DFS search for performance. See PR #320.
        node_count = [0]
        node_limit = 5000 / len(dag.roots)
        def recurse_nodes(task, visited):
            visited.add(task)
            node_count[0] += 1
            children = [
                recurse_nodes(t, visited) for t in task.upstream_list
                if node_count[0] < node_limit or t not in visited]
            # D3 tree uses children vs _children to define what is
            # expanded or not. The following block makes it such that
            # repeated nodes are collapsed by default.
            children_key = 'children'
            if task.task_id not in expanded:
                expanded.append(task.task_id)
            elif children:
                children_key = "_children"
            return {
                'name': task.task_id,
                'instances': [
                    utils.alchemy_to_dict(
                        task_instances.get((task.task_id, d))) or {
                            'execution_date': d.isoformat(),
                            'task_id': task.task_id
                        }
                    for d in dates],
                children_key: children,
                'num_dep': len(task.upstream_list),
                'operator': task.task_type,
                'retries': task.retries,
                'owner': task.owner,
                'start_date': task.start_date,
                'end_date': task.end_date,
                'depends_on_past': task.depends_on_past,
                'ui_color': task.ui_color,
            }
        if len(dag.roots) > 1:
            # d3 likes a single root
            data = {
                'name': 'root',
                'instances': [],
                'children': [recurse_nodes(t, set()) for t in dag.roots]
            }
        elif len(dag.roots) == 1:
            data = recurse_nodes(dag.roots[0], set())
        else:
            flash("No tasks found.", "error")
            data = []
        data = json.dumps(data, indent=4, default=utils.json_ser)
        session.commit()
        session.close()
        return self.render(
            'airflow/tree.html',
            operators=sorted(
                list(set([op.__class__ for op in dag.tasks])),
                key=lambda x: x.__name__
            ),
            root=root,
            form=form,
            dag=dag, data=data, blur=blur)
    @expose('/graph')
    @login_required
    @wwwutils.gzipped
    def graph(self):
